// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;

    function setUp() public { c = new PuttyV2("", 0, address(this)); }

    function testFuzz_property(uint256 duration, address to) public {
        vm.assume(to != address(0) && to != address(c));
        duration = bound(duration, 1 days, 9_999 days);

        // adversarial counterparties: maker is a contract with a valid ERC1271
        // signature checker, baseAsset is a mock ERC20 that accepts transfers.
        Maker maker = new Maker();
        MockERC20 base = new MockERC20();

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: true,
            isLong: true,
            baseAsset: address(base),
            strike: 0,
            premium: 0,
            duration: duration,
            expiration: block.timestamp + 10 days,
            nonce: 0,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        uint256[] memory floorAssetTokenIds = new uint256[](0);
        bytes memory sig = hex"deadbeef";

        c.fillOrder(order, sig, floorAssetTokenIds);

        uint256 id = uint256(c.hashOrder(order));
        vm.prank(address(maker));
        c.transferFrom(address(maker), to, id);

        assertTrue(c.ownerOf(id) == to);
    }
}

contract Maker {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }
}

contract MockERC20 {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    function transfer(address, uint256) external pure returns (bool) {
        return true;
    }
}
